58	  /**
59	   * Regular response.
60	   * 1. Update MultipartKey in MultipartInfoTable with new PartKeyInfo
61	   * 2. Delete openKey from OpenKeyTable
62	   * 3. If old key or uncommitted (pseudo) key exists, put it in DeletedTable
63	   */
64	  @SuppressWarnings("checkstyle:ParameterNumber")
65	  public S3MultipartUploadCommitPartResponse(@Nonnull OMResponse omResponse,
66	      String multipartKey, String openKey,
67	      @Nullable OmMultipartKeyInfo omMultipartKeyInfo,
68	      @Nullable Map<String, RepeatedOmKeyInfo> keyToDeleteMap,
69	      @Nullable OmKeyInfo openPartKeyInfoToBeDeleted,
70	      @Nonnull OmBucketInfo omBucketInfo,
71	      @Nonnull BucketLayout bucketLayout) {
72	    super(omResponse, bucketLayout);
73	    this.multipartKey = multipartKey;
74	    this.openKey = openKey;
75	    this.omMultipartKeyInfo = omMultipartKeyInfo;
76	    this.keyToDeleteMap = keyToDeleteMap;
77	    this.openPartKeyInfoToBeDeleted = openPartKeyInfoToBeDeleted;
78	    this.omBucketInfo = omBucketInfo;
79	  }
80	
81	  @Override
82	  public void checkAndUpdateDB(OMMetadataManager omMetadataManager,
83	      BatchOperation batchOperation) throws IOException {
84	
85	    if (getOMResponse().getStatus() == NO_SUCH_MULTIPART_UPLOAD_ERROR) {
86	      // Means by the time we try to commit part, some one has aborted this
87	      // multipart upload. So, delete this part information.
88	
89	      RepeatedOmKeyInfo repeatedOmKeyInfo =
90	          OmUtils.prepareKeyForDelete(openPartKeyInfoToBeDeleted,
91	              openPartKeyInfoToBeDeleted.getUpdateID()
92	          );
93	      // multi-part key format is volumeName/bucketName/keyName/uploadId
94	      String deleteKey = omMetadataManager.getOzoneDeletePathKey(
95	          openPartKeyInfoToBeDeleted.getObjectID(), multipartKey);
96	
97	      omMetadataManager.getDeletedTable().putWithBatch(batchOperation,
98	          deleteKey, repeatedOmKeyInfo);
99	    }
100	
101	    if (getOMResponse().getStatus() == OK) {
102	      addToDBBatch(omMetadataManager, batchOperation);
103	    }
104	  }
105	
106	  @Override
107	  public void addToDBBatch(OMMetadataManager omMetadataManager,
108	      BatchOperation batchOperation) throws IOException {
109	    // Delete old (overwritten) part upload and uncommitted parts
110	    if (keyToDeleteMap != null) {
111	      for (Map.Entry<String, RepeatedOmKeyInfo> entry : keyToDeleteMap.entrySet()) {
112	        omMetadataManager.getDeletedTable().putWithBatch(batchOperation,
113	            entry.getKey(), entry.getValue());
114	      }
115	    }
116	
117	    omMetadataManager.getMultipartInfoTable().putWithBatch(batchOperation,
118	        multipartKey, omMultipartKeyInfo);
119	
120	    //  This information has been added to multipartKeyInfo. So, we can
121	    //  safely delete part key info from open key table.
122	    omMetadataManager.getOpenKeyTable(getBucketLayout())
123	        .deleteWithBatch(batchOperation, openKey);
124	
125	    // update bucket usedBytes.
126	    omMetadataManager.getBucketTable().putWithBatch(batchOperation,
127	        omMetadataManager.getBucketKey(omBucketInfo.getVolumeName(),
128	            omBucketInfo.getBucketName()), omBucketInfo);
129	  }
