+  protected FileEncryptionInfo getFileEncryptionInfo(KeyArgs keyArgs) {
+    FileEncryptionInfo encryptionInfo = null;
+    if (keyArgs.hasFileEncryptionInfo()) {
+      encryptionInfo = OMPBHelper.convert(keyArgs.getFileEncryptionInfo());
+    }
